import com.ezylang.evalex.operators.OperatorIfc;
import org.junit.Test;
import org.mockito.Mockito;

import java.util.List;

import static org.junit.Assert.*;

public class TokenizerTest {

    @Test
    public void parseSyntaxErrorExceptionTest() {
        ExpressionConfiguration configuration = Mockito.mock(ExpressionConfiguration.class);
        String expressionString = "2+2/";
        Tokenizer tokenizer = new Tokenizer(expressionString, configuration);

        try {
            tokenizer.parse();
            fail("Expected ParseException to be thrown");
        } catch (ParseException e) {
            assertTrue(e.getMessage().contains("Syntax error"));
        }
    }

    @Test
    public void parseInvalidCharacterExceptionTest() {
        ExpressionConfiguration configuration = Mockito.mock(ExpressionConfiguration.class);
        String expressionString = "2+2#";
        Tokenizer tokenizer = new Tokenizer(expressionString, configuration);

        try {
            tokenizer.parse();
            fail("Expected ParseException to be thrown");
        } catch (ParseException e) {
            assertTrue(e.getMessage().contains("Invalid character"));
        }
    }

    @Test
    public void parseStringLiteralInvalidEscapeExceptionTest() {
        ExpressionConfiguration configuration = Mockito.mock(ExpressionConfiguration.class);
        String expressionString = "\"invalid\\escape\"";
        Tokenizer tokenizer = new Tokenizer(expressionString, configuration);

        try {
            tokenizer.parseStringLiteral();
            fail("Expected ParseException to be thrown");
        } catch (ParseException e) {
            assertTrue(e.getMessage().contains("Invalid escape"));
        }
    }

    @Test
    public void parseStringLiteralPrematureEndExceptionTest() {
        ExpressionConfiguration configuration = Mockito.mock(ExpressionConfiguration.class);
        String expressionString = "\"premature end";
        Tokenizer tokenizer = new Tokenizer(expressionString, configuration);

        try {
            tokenizer.parseStringLiteral();
            fail("Expected ParseException to be thrown");
        } catch (ParseException e) {
            assertTrue(e.getMessage().contains("Premature end of string"));
        }
    }

    @Test
    public void parseFunctionTokensTest() throws ParseException {
        FunctionIfc functionMock = Mockito.mock(FunctionIfc.class);
        Mockito.when(functionMock.getName()).thenReturn("abc");
        ExpressionConfiguration configuration = Mockito.mock(ExpressionConfiguration.class);
        Mockito.when(configuration.getFunction("abc")).thenReturn(functionMock);
        String expressionString = "abc(123)";
        Tokenizer tokenizer = new Tokenizer(expressionString, configuration);

        List<Token> tokens = tokenizer.parse();
        assertEquals(3, tokens.size());
        assertEquals(TokenType.FUNCTION, tokens.get(0).getType());
        assertEquals(TokenType.OPEN_PAREN, tokens.get(1).getType());
        assertEquals(TokenType.CLOSE_PAREN, tokens.get(2).getType());
    }

    @Test
    public void parseOperatorTokensTest() throws ParseException {
        OperatorIfc operatorMock = Mockito.mock(OperatorIfc.class);
        Mockito.when(operatorMock.getOperator()).thenReturn("+");
        ExpressionConfiguration configuration = Mockito.mock(ExpressionConfiguration.class);
        Mockito.when(configuration.getOperator("+")).thenReturn(operatorMock);
        String expressionString = "123+456";
        Tokenizer tokenizer = new Tokenizer(expressionString, configuration);

        List<Token> tokens = tokenizer.parse();
        assertEquals(3, tokens.size());
        assertEquals(TokenType.NUMBER, tokens.get(0).getType());
        assertEquals(TokenType.OPERATOR, tokens.get(1).getType());
        assertEquals(TokenType.NUMBER, tokens.get(2).getType());
    }

}
